# Generated by trgen <version>
set -euo pipefail
cd "$(dirname "$0")"
CONGOCC_JAR="${CONGOCC_JAR:-$HOME/congo-parser-generator/bin/congocc.jar}"
JAVA="${JAVA:-java}"
JAVAC="${JAVAC:-javac}"
# Keep parser rule names unless they collide with token class names. An explicit
# prefix overrides the automatic choice.
CONGOCC_RULE_PREFIX="${CONGOCC_RULE_PREFIX:-}"
if [[ ! -f "$CONGOCC_JAR" ]]; then
  echo "CongoCC JAR not found: $CONGOCC_JAR (set CONGOCC_JAR)" >&2
  exit 1
fi
# Keep the conversion in the Trash pipeline: parse .g4, evaluate the XQuery4
# translator, then save the resulting CongoCC grammar for CongoCC itself.
source_bundle=$(mktemp)
grammar_bundle=$(mktemp)
conversion_error=$(mktemp)
trap 'rm -f "$source_bundle" "$grammar_bundle" "$conversion_error"' EXIT
parse_cmd=(dotnet trash parse)
query_cmd=(dotnet trash xquery)
combine_cmd=(dotnet trash combine)
if [[ -n "${TRPARSE_DLL:-}" ]]; then parse_cmd=(dotnet "$TRPARSE_DLL"); fi
if [[ -n "${TRXQUERY_DLL:-}" ]]; then query_cmd=(dotnet "$TRXQUERY_DLL"); fi
if [[ -n "${TRCOMBINE_DLL:-}" ]]; then combine_cmd=(dotnet "$TRCOMBINE_DLL"); fi
grammar_files=(<tool_grammar_files:{g | "<g>" }; separator=" ">)
"${parse_cmd[@]}" "${grammar_files[@]}" > "$source_bundle"
if (( ${#grammar_files[@]} > 1 )); then
  # trcombine selects the top-level parser and lexer, follows imports, and
  # emits one combined .g4.pt while removing the source .pt members.
  "${combine_cmd[@]}" -f "$source_bundle" > "$grammar_bundle"
else
  cp "$source_bundle" "$grammar_bundle"
fi
interp_cmd=(dotnet trash interp)
if [[ -n "${TRINTERP_DLL:-}" ]]; then interp_cmd=(dotnet "$TRINTERP_DLL"); fi
scan_specs=$("${interp_cmd[@]}" --congocc-scans -f "$grammar_bundle")
render_grammar() {
  if ! "${query_cmd[@]}" -f "$grammar_bundle" -q convert.xq \
    "$CONGOCC_RULE_PREFIX" "$scan_specs" 2>"$conversion_error" |
    "${interp_cmd[@]}" --congocc-expand-unicode > <grammar_name>.ccc; then
    if [[ -s "$conversion_error" ]]; then head -n 1 "$conversion_error" >&2; fi
    return 1
  fi
}
render_grammar
if [[ -z "$CONGOCC_RULE_PREFIX" ]]; then
  collision=$(awk '
    /(^| )(TOKEN|SKIP) : / {
      split($0, parts, " : ")
      name = substr(parts[2], 2)
      sub(/^[#?]/, "", name)
      tokens[tolower(name)] = 1
    }
    /^[[:alpha:]_][[:alnum:]_]* : / {
      split($0, parts, " : ")
      if (tokens[tolower(parts[1])]) { print parts[1]; exit }
    }
  ' <grammar_name>.ccc)
  if [[ -n "$collision" ]]; then
    echo "CongoCC: parser rule '$collision' conflicts with a token class; using ParserRule_ prefix." >&2
    CONGOCC_RULE_PREFIX=ParserRule_
    render_grammar
  fi
fi
printf '%s' "$CONGOCC_RULE_PREFIX" > parser-rule-prefix.txt
# Discard stale Java/AST classes when changing the parser-rule prefix.
rm -rf generated classes
"$JAVA" -jar "$CONGOCC_JAR" <grammar_name>.ccc
mkdir -p classes
"$JAVAC" -d classes Test.java generated/*.java generated/ast/*.java
